const queries = [
  {
    group: "core_disease",
    query: `all:hyperuricemia OR all:gout OR all:"monosodium urate" OR all:"urate-lowering therapy"`
  },
  {
    group: "ai_methods",
    query: `(all:hyperuricemia OR all:gout OR all:rheumatology) AND (all:"machine learning" OR all:"deep learning" OR all:"explainable AI" OR all:"graph neural network" OR all:"multi-omics")`
  },
  {
    group: "clinical_prediction",
    query: `(all:gout OR all:hyperuricemia) AND (all:"risk stratification" OR all:"precision medicine" OR all:"predictive analytics" OR all:"clinical validation")`
  },
  {
    group: "comorbidities",
    query: `all:hyperuricemia AND (all:"chronic kidney disease" OR all:"cardiovascular disease" OR all:"electronic health records" OR all:"wearable")`
  }
];
return queries.map(q => ({ json: q }));

const xml = $input.first().json.data;
const group = $('Build Queries').item.json.group;

function extractBetween(text, open, close) {
  const results = [];
  let start = 0;
  while (true) {
    const s = text.indexOf(open, start);
    if (s === -1) break;
    const e = text.indexOf(close, s + open.length);
    if (e === -1) break;
    results.push(text.substring(s + open.length, e).trim());
    start = e + close.length;
  }
  return results;
}

const entries = extractBetween(xml, '<entry>', '</entry>');

const articles = entries.map(entry => {
  const arxiv_id_raw = extractBetween(entry, '<id>', '</id>')[0] || '';
  const arxiv_id = arxiv_id_raw.replace('http://arxiv.org/abs/', '').trim();
  const title = (extractBetween(entry, '<title>', '</title>')[0] || '').replace(/\s+/g, ' ').trim();
  const abstract = (extractBetween(entry, '<summary>', '</summary>')[0] || '').replace(/\s+/g, ' ').trim();
  const published = extractBetween(entry, '<published>', '</published>')[0] || '';
  const authors = extractBetween(entry, '<name>', '</name>').join(', ');
  return {
    arxiv_id,
    title,
    abstract,
    authors,
    url: `https://arxiv.org/abs/${arxiv_id}`,
    published_date: published.substring(0, 10),
    group
  };
}).filter(a => a.arxiv_id);

return articles.map(a => ({ json: a }));

const items = $('Compose Record').all();
const today = new Date().toISOString().split('T')[0];

let html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><style>
body { font-family: Calibri, Arial, sans-serif; padding: 40px; color: #222; }
h1 { color: #1a4d8c; border-bottom: 2px solid #1a4d8c; padding-bottom: 10px; }
h2 { color: #1a4d8c; margin-top: 30px; }
h3 { color: #444; }
.article { margin-bottom: 40px; padding: 20px; border-left: 4px solid #1a4d8c; background: #f9f9f9; }
.meta { color: #666; font-size: 0.9em; margin-bottom: 10px; }
.summary { white-space: pre-wrap; }
a { color: #1a4d8c; }
</style></head><body>`;

html += `<h1>📚 arXiv Дайджест: Подагра и ИИ</h1>`;
html += `<p><strong>Дата:</strong> ${today}<br><strong>Новых статей:</strong> ${items.length}</p>`;

for (const item of items) {
  const a = item.json;
  const summaryHtml = (a.summary || '').replace(/## ([^\n]+)/g, '<h3>$1</h3>').replace(/\n/g, '<br>');
  html += `<div class="article">
    <h2>${a.title}</h2>
    <div class="meta">
      <strong>Авторы:</strong> ${a.authors}<br>
      <strong>Дата:</strong> ${a.published_date}<br>
      <strong>arXiv:</strong> <a href="${a.url}">${a.arxiv_id}</a>
    </div>
    <div class="summary">${summaryHtml}</div>
  </div>`;
}
html += `</body></html>`;

const buffer = Buffer.from(html, 'utf-8');
return [{
  json: { filename: `arxiv_digest_${today}.doc`, count: items.length },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/msword',
      fileName: `arxiv_digest_${today}.doc`,
      fileExtension: 'doc'
    }
  }
}];
